145→				const sessionUpdate = update.sessionUpdate as string | undefined;
146→
147→				if (sessionUpdate === 'assistant_text' || sessionUpdate === 'assistant') {
148→					const content = (update.text ?? update.content ?? '') as string;
149→					if (content) {
