    92→	}
    93→
    94→	const keys = Object.keys(obj);
    95→	if (keys.length <= 3) return keys.join(', ');
    96→	return `${keys.length} params`;
    97→}
    98→
    99→function truncate(str: string, max: number): string {
   100→	if (str.length <= max) return str;
   101→	return str.slice(0, max) + '\u2026';
   102→}
   103→
   104→/**
   105→ * Parse raw session events into structured display blocks.
   106→ *
   107→ * AC: @ui-session-stream ac-1
   108→ */
   109→export function parseEventsToBlocks(events: SessionEvent[]): DisplayBlock[] {
   110→	const blocks: DisplayBlock[] = [];
   111→	const toolCalls = new Map<string, ToolCallBlock>();
   112→
   113→	for (const event of events) {
   114→		const data = event.data as Record<string, unknown> | null;
   115→		if (!data) continue;
   116→
   117→		switch (event.type) {
   118→			case 'session.start': {
   119→				blocks.push({
   120→					type: 'system',
   121→					label: 'Session started',
   122→					detail: data.agent_type ? `Agent: ${data.agent_type}` : undefined,
   123→					timestamp: event.ts,
   124→					seq: event.seq,
   125→				});
   126→				break;
   127→			}
   128→
   129→			case 'session.end':
   130→			case 'session.wrapup': {
   131→				blocks.push({
   132→					type: 'system',
   133→					label: event.type === 'session.end' ? 'Session ended' : 'Session wrapping up',
   134→					detail: data.reason ? String(data.reason) : undefined,
   135→					timestamp: event.ts,
   136→					seq: event.seq,
   137→				});
   138→				break;
   139→			}
   140→
   141→			case 'session.update': {
   142→				const update = data.update as Record<string, unknown> | undefined;
   143→				if (!update) break;
   144→
   145→				const sessionUpdate = update.sessionUpdate as string | undefined;
   146→
   147→				if (sessionUpdate === 'assistant_text' || sessionUpdate === 'assistant') {
   148→					const content = (update.text ?? update.content ?? '') as string;
   149→					if (content) {
   150→						// Merge consecutive message blocks
   151→						const lastBlock = blocks[blocks.length - 1];
   152→						if (lastBlock?.type === 'message') {
   153→							lastBlock.content += content;
   154→						} else {
   155→							blocks.push({
   156→								type: 'message',
   157→								content,
   158→								timestamp: event.ts,
   159→								seq: event.seq,
   160→							});
   161→						}
   162→					}
   163→				} else if (sessionUpdate === 'thinking' || sessionUpdate === 'assistant_thinking') {
   164→					const content = (update.text ?? update.content ?? '') as string;
   165→					if (content) {
   166→						const lastBlock = blocks[blocks.length - 1];
   167→						if (lastBlock?.type === 'thinking') {
   168→							lastBlock.content += content;
   169→						} else {
   170→							blocks.push({
   171→								type: 'thinking',
   172→								content,
   173→								timestamp: event.ts,
   174→								seq: event.seq,
   175→							});
   176→						}
   177→					}
   178→				} else if (sessionUpdate === 'tool_call') {
   179→					const toolCallId = (update.toolCallId ?? update.tool_call_id ?? update.id ?? '') as string;
   180→					const toolName = (update.tool ?? update.toolName ?? update.name ?? 'unknown') as string;
   181→					const rawInput = update.rawInput ?? update.input;
   182→
   183→					const block: ToolCallBlock = {
   184→						type: 'tool_call',
   185→						toolName,
   186→						toolCallId,
   187→						input: rawInput,
   188→						status: 'running',
   189→						startedAt: event.ts,
   190→						seq: event.seq,
   191→					};
   192→
   193→					toolCalls.set(toolCallId, block);
   194→					blocks.push(block);
   195→				} else if (sessionUpdate === 'tool_result') {
   196→					const toolCallId = (update.toolCallId ?? update.tool_call_id ?? update.id ?? '') as string;
   197→					const existing = toolCalls.get(toolCallId);
   198→
   199→					if (existing) {
   200→						existing.output = update.output ?? update.rawOutput ?? update.content;
   201→						existing.status = (update.error || update.isError) ? 'failed' : 'completed';
   202→						existing.completedAt = event.ts;
   203→						existing.durationMs = event.ts - existing.startedAt;
   204→					}
   205→				}
   206→				break;
   207→			}
   208→
   209→			case 'tool.call': {
   210→				const toolName = (data.tool ?? data.name ?? 'unknown') as string;
   211→				const toolCallId = (data.toolCallId ?? data.tool_call_id ?? data.id ?? `tool-${event.seq}`) as string;
   212→
   213→				const block: ToolCallBlock = {
   214→					type: 'tool_call',
   215→					toolName,
   216→					toolCallId,
   217→					input: data.input ?? data.rawInput ?? data.args,
   218→					status: 'running',
   219→					startedAt: event.ts,
   220→					seq: event.seq,
   221→				};
   222→
   223→				toolCalls.set(toolCallId, block);
   224→				blocks.push(block);
   225→				break;
   226→			}
   227→
   228→			case 'tool.result': {
   229→				const toolCallId = (data.toolCallId ?? data.tool_call_id ?? data.id ?? '') as string;
   230→				const existing = toolCalls.get(toolCallId);
   231→
   232→				if (existing) {
   233→					existing.output = data.output ?? data.rawOutput ?? data.content;
   234→					existing.status = (data.error || data.isError) ? 'failed' : 'completed';
   235→					existing.completedAt = event.ts;
   236→					existing.durationMs = event.ts - existing.startedAt;
   237→				}
   238→				break;
   239→			}
   240→
   241→			case 'note': {
   242→				blocks.push({
   243→					type: 'system',
   244→					label: 'Note',
   245→					detail: typeof data.message === 'string' ? data.message : JSON.stringify(data),
   246→					timestamp: event.ts,
   247→					seq: event.seq,
   248→				});
   249→				break;
   250→			}
   251→
   252→			case 'agent.dispatched':
   253→			case 'agent.started':
   254→			case 'agent.completed':
   255→			case 'agent.failed':
   256→			case 'agent.timeout': {
   257→				const labelMap: Record<string, string> = {
   258→					'agent.dispatched': 'Agent dispatched',
   259→					'agent.started': 'Agent started',
   260→					'agent.completed': 'Agent completed',
   261→					'agent.failed': 'Agent failed',
   262→					'agent.timeout': 'Agent timed out',
   263→				};
   264→				blocks.push({
   265→					type: 'system',
   266→					label: labelMap[event.type] ?? event.type,
   267→					detail: data.task_ref ? `Task: ${data.task_ref}` : undefined,
   268→					timestamp: event.ts,
   269→					seq: event.seq,
   270→				});
   271→				break;
   272→			}
   273→
   274→			case 'prompt.sent': {
   275→				const phase = data.phase as string | undefined;
   276→				const iteration = data.iteration as number | undefined;
   277→				if (phase) {
   278→					blocks.push({
   279→						type: 'system',
   280→						label: `Iteration ${iteration ?? '?'}`,
   281→						detail: `Phase: ${phase}`,
   282→						timestamp: event.ts,
   283→						seq: event.seq,
   284→					});
   285→				}
   286→				break;
   287→			}
   288→
   289→			case 'iteration.timeout': {
   290→				blocks.push({
   291→					type: 'system',
   292→					label: 'Iteration timeout',
   293→					timestamp: event.ts,
   294→					seq: event.seq,
   295→				});
   296→				break;
   297→			}
   298→		}
   299→	}
   300→
   301→	return blocks;
   302→}
   303→
   304→/**
   305→ * Format a duration in milliseconds to a human-readable string.
   306→ */
   307→export function formatDuration(ms: number): string {
   308→	if (ms < 1000) return `${ms}ms`;
   309→	const secs = Math.floor(ms / 1000);
   310→	const mins = Math.floor(secs / 60);
   311→	const hours = Math.floor(mins / 60);
   312→	if (hours > 0) return `${hours}h ${mins % 60}m`;
   313→	if (mins > 0) return `${mins}m ${secs % 60}s`;
   314→	return `${secs}s`;
   315→}
   316→
   317→/**
   318→ * Format a timestamp to a time string.
   319→ */
   320→export function formatTime(ts: number): string {
   321→	const d = new Date(ts);
   322→	return d.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
   323→}
   324→
   325→/**
   326→ * Format elapsed milliseconds to human-readable string (e.g. "2h 5m", "30s").
   327→ */
   328→export function formatElapsed(ms: number): string {
   329→	const secs = Math.floor(ms / 1000);
   330→	const mins = Math.floor(secs / 60);
   331→	const hours = Math.floor(mins / 60);
   332→
   333→	if (hours > 0) return `${hours}h ${mins % 60}m`;
   334→	if (mins > 0) return `${mins}m ${secs % 60}s`;
   335→	return `${secs}s`;
   336→}
   337→
   338→/**
   339→ * Format a relative age string from a date (e.g. "5m", "2h", "3d").
   340→ */
   341→export function formatAge(dateStr: string): string {
   342→	const now = Date.now();
   343→	const then = new Date(dateStr).getTime();
   344→	const diffMs = now - then;
   345→	const diffMins = Math.floor(diffMs / 60000);
   346→	const diffHours = Math.floor(diffMins / 60);
   347→	const diffDays = Math.floor(diffHours / 24);
   348→
   349→	if (diffMins < 1) return 'just now';
   350→	if (diffMins < 60) return `${diffMins}m`;
   351→	if (diffHours < 24) return `${diffHours}h`;
   352→	if (diffDays < 30) return `${diffDays}d`;
   353→	return `${Math.floor(diffDays / 30)}mo`;
   354→}
   355→
   356→/**
   357→ * Extract unique file paths that were changed during a session.
   358→ * Looks at Write, Edit, and NotebookEdit tool calls.
   359→ *
   360→ * AC: @ui-session-stream ac-4 — Files changed during session.
   361→ */
   362→/**
   363→ * Compute the distance from the bottom of a scroll container.
   364→ * Used by SessionStream.svelte for auto-scroll detection.
   365→ *
   366→ * AC: @ui-session-stream ac-3
   367→ */
   368→export function computeScrollDistance(scrollHeight: number, scrollTop: number, clientHeight: number): number {
   369→	return scrollHeight - scrollTop - clientHeight;
   370→}
   371→
   372→/**
   373→ * Determine whether auto-scroll should be active based on scroll position.
   374→ * Returns true when the user is within the threshold of the bottom.
   375→ *
   376→ * AC: @ui-session-stream ac-3
   377→ */
   378→export const AUTO_SCROLL_THRESHOLD = 100;
   379→
   380→export function shouldAutoScroll(scrollHeight: number, scrollTop: number, clientHeight: number): boolean {
   381→	return computeScrollDistance(scrollHeight, scrollTop, clientHeight) <= AUTO_SCROLL_THRESHOLD;
   382→}
   383→
   384→/**
   385→ * Determine whether the "jump to bottom" button should be visible.
   386→ * Shown when not auto-scrolling AND there is content to jump to.
   387→ *
   388→ * AC: @ui-session-stream ac-3
   389→ */
   390→export function shouldShowJumpButton(autoScrolling: boolean, isLive: boolean, blockCount: number): boolean {
   391→	return !autoScrolling && (isLive || blockCount > 0);
   392→}
   393→
   394→/**
   395→ * Accumulate streaming text from agent_text_chunk WebSocket events.
   396→ * Only accumulates for the target session. Returns updated streaming text.
   397→ *
   398→ * AC: @ui-session-stream ac-2
   399→ */
   400→export function accumulateStreamingText(
   401→	currentText: string,
   402→	event: { event: string; data: unknown },
   403→	targetSessionId: string,
   404→): string {
   405→	if (event.event !== 'agent_text_chunk') return currentText;
   406→	const data = event.data as { session_id?: string; text?: string } | null;
   407→	if (!data || data.session_id !== targetSessionId || !data.text) return currentText;
   408→	return currentText + data.text;
   409→}
   410→
   411→/**
   412→ * Determine the last sequence number from an events array.
   413→ * Returns -1 if the array is empty.
   414→ *
   415→ * AC: @ui-session-stream ac-2
   416→ */
   417→export function getLastSeq(events: Array<{ seq: number }>): number {
   418→	if (events.length === 0) return -1;
   419→	return events[events.length - 1].seq;
   420→}
   421→
   422→const WRITE_TOOLS = new Set(['Write', 'Edit', 'NotebookEdit']);
   423→
   424→export function extractFilesChanged(blocks: DisplayBlock[]): string[] {
   425→	const files = new Set<string>();
   426→	for (const block of blocks) {
   427→		if (block.type !== 'tool_call') continue;
   428→		if (!WRITE_TOOLS.has(block.toolName)) continue;
   429→		const input = block.input as Record<string, unknown> | null;
   430→		if (!input) continue;
   431→		const filePath = (input.file_path ?? input.notebook_path) as string | undefined;
   432→		if (filePath) files.add(filePath);
   433→	}
   434→	return [...files].sort();
   435→}
