   100→	{/if}
   101→
   102→	{#if loading}
   103→		<div class="text-center text-muted-foreground" data-testid="loading">Loading observations...</div>
   104→	{:else if observations.length === 0}
   105→		<div class="text-center text-muted-foreground" data-testid="observations-empty">
   106→			<p>No unresolved observations.</p>
   107→			<p class="text-sm">Observations are captured during work sessions.</p>
   108→		</div>
   109→	{:else}
   110→		<div class="flex flex-col gap-3">
   111→			{#each observations as obs (obs._ulid)}
   112→				<!-- AC: @web-dashboard ac-22 - Show type icons -->
   113→				<Card data-testid="observation-item">
   114→					<CardHeader class="pb-3">
   115→						<div class="flex items-start gap-3">
   116→							<div class={`mt-0.5 ${typeColors[obs.type]}`} data-testid="observation-type-icon">
   117→								<svelte:component this={typeIcons[obs.type]} class="h-5 w-5" />
   118→							</div>
   119→							<div class="flex-1">
   120→								<div class="flex items-center gap-2 mb-2">
   121→									<Badge variant="outline" data-testid="observation-type">{typeLabels[obs.type]}</Badge>
   122→									<span class="text-xs text-muted-foreground">{formatDate(obs.created_at)}</span>
   123→								</div>
   124→								<p class="text-sm leading-relaxed" data-testid="observation-content">{obs.content}</p>
   125→								{#if obs.context}
   126→									<p class="mt-2 text-xs text-muted-foreground border-l-2 border-muted pl-3">
   127→										{obs.context}
   128→									</p>
   129→								{/if}
   130→							</div>
   131→						</div>
   132→					</CardHeader>
   133→				</Card>
   134→			{/each}
   135→		</div>
   136→	{/if}
   137→</div>
   138→
```

